using Gravicode.Science.SciNet;
using Xunit;
using static Gravicode.Science.Tests.SciNet.StatsTestsAssert;
using R = Gravicode.Science.Tests.SciNet.StatsTestsRef;

namespace Gravicode.Science.Tests.SciNet;

/// <summary>t-tests, ANOVA and rank tests against scipy 1.17.1 (reference values generated by scipy).</summary>
public class StatsLocationTestTests
{
    private const double Rt = 1e-10;

    [Fact]
    public void TtestOneSampleMatchesScipy()
    {
        foreach (var (name, alt) in Alternatives)
        {
            var r = Stats.Ttest1samp(R.X, 0.3, alt);
            var ci = r.ConfidenceInterval(0.9);
            Close($"ttest_1samp/{name}", Rt, 1e-14, r.Statistic, r.Pvalue, r.Df, ci.Low, ci.High);
        }
    }

    [Fact]
    public void TtestIndependentMatchesScipy()
    {
        foreach (var (name, alt) in Alternatives)
            foreach (var ev in new[] { true, false })
            {
                var key = ev ? "True" : "False";
                var r = Stats.TtestInd(R.X, R.Y, ev, alt);
                var ci = r.ConfidenceInterval();
                Close($"ttest_ind/{key}/{name}", Rt, 1e-14, r.Statistic, r.Pvalue, r.Df, ci.Low, ci.High);
                var tr = Stats.TtestInd(R.X, R.Y, ev, alt, trim: 0.2);
                Close($"ttest_ind_trim/{key}/{name}", Rt, 1e-14, tr.Statistic, tr.Pvalue, tr.Df);
                var fs = Stats.TtestIndFromStats(1.2, 0.9, 14, 0.7, 1.4, 21, ev, alt);
                Close($"ttest_from_stats/{key}/{name}", Rt, 1e-14, fs.Statistic, fs.Pvalue);
            }
    }

    [Fact]
    public void TtestRelatedMatchesScipy()
    {
        foreach (var (name, alt) in Alternatives)
        {
            var r = Stats.TtestRel(R.PA, R.PB, alt);
            var ci = r.ConfidenceInterval();
            Close($"ttest_rel/{name}", Rt, 1e-14, r.Statistic, r.Pvalue, r.Df, ci.Low, ci.High);
        }
    }

    [Fact]
    public void TtestNanPolicy()
    {
        var a = new[] { 1.0, 2.0, double.NaN, 4.0 };
        Assert.True(double.IsNaN(Stats.Ttest1samp(a, 0).Statistic));
        Assert.Throws<ArgumentException>(() => Stats.Ttest1samp(a, 0, nanPolicy: NanPolicy.Raise));
        var omit = Stats.Ttest1samp(a, 0, nanPolicy: NanPolicy.Omit);
        var direct = Stats.Ttest1samp([1.0, 2.0, 4.0], 0);
        Assert.Equal(direct.Statistic, omit.Statistic);
    }

    [Fact]
    public void AnovaFamilyMatchesScipy()
    {
        var r = Stats.FOneway(R.X, R.Y, R.Z);
        Close("f_oneway", Rt, 1e-14, r.Statistic, r.Pvalue);
        r = Stats.FOneway([R.X, R.Y, R.Z], equalVar: false);
        Close("f_oneway_welch", Rt, 1e-14, r.Statistic, r.Pvalue);
        r = Stats.AlexanderGovern(R.X, R.Y, R.Z);
        Close("alexandergovern", Rt, 1e-14, r.Statistic, r.Pvalue);
        r = Stats.Kruskal(R.T1, R.T2, R.T3);
        Close("kruskal_ties", Rt, 1e-14, r.Statistic, r.Pvalue);
        r = Stats.Kruskal(R.X, R.Y, R.Z);
        Close("kruskal", Rt, 1e-14, r.Statistic, r.Pvalue);
        r = Stats.FriedmanChiSquare(R.T1[..12], R.T2[..12], R.T3);
        Close("friedman_ties", Rt, 1e-14, r.Statistic, r.Pvalue);
        r = Stats.FriedmanChiSquare(R.X[..20], R.Y[..20], R.Z);
        Close("friedman", Rt, 1e-14, r.Statistic, r.Pvalue);
    }

    [Fact]
    public void FOnewayDegenerateCases()
    {
        Assert.True(double.IsPositiveInfinity(Stats.FOneway([1.0, 1, 1], [2.0, 2, 2]).Statistic));
        Assert.True(double.IsNaN(Stats.FOneway([1.0, 1, 1], [1.0, 1, 1]).Statistic));
    }

    [Fact]
    public void MannWhitneyMatchesScipy()
    {
        foreach (var (name, alt) in Alternatives)
        {
            foreach (var meth in new[] { "exact", "asymptotic" })
                foreach (var cont in new[] { true, false })
                {
                    var r = Stats.MannWhitneyU(R.S1, R.S2, cont, alt, meth);
                    Close($"mwu_small/{meth}/{(cont ? "True" : "False")}/{name}", Rt, 1e-14, r.Statistic, r.Pvalue);
                }
            var a = Stats.MannWhitneyU(R.X, R.Y, alternative: alt);
            Close($"mwu/{name}", Rt, 1e-14, a.Statistic, a.Pvalue);
            var t = Stats.MannWhitneyU(R.T1, R.T2, alternative: alt);
            Close($"mwu_ties/{name}", Rt, 1e-14, t.Statistic, t.Pvalue);
            var e = Stats.MannWhitneyU(R.X[..10], R.Y[..12], alternative: alt, method: "exact");
            Close($"mwu_exact/{name}", 1e-9, 1e-14, e.Statistic, e.Pvalue);
            var rs = Stats.Ranksums(R.X, R.Y, alt);
            Close($"ranksums/{name}", Rt, 1e-14, rs.Statistic, rs.Pvalue);
            var bm = Stats.BrunnerMunzel(R.T1, R.T2, alt);
            Close($"brunnermunzel/t/{name}", Rt, 1e-14, bm.Statistic, bm.Pvalue);
            bm = Stats.BrunnerMunzel(R.X, R.Y, alt, "normal");
            Close($"brunnermunzel/normal/{name}", Rt, 1e-14, bm.Statistic, bm.Pvalue);
        }
    }

    [Fact]
    public void MannWhitneyExactDistributionAgreesWithEnumeration()
    {
        // Brute force: every split of ranks 1..7 into 3 + 4, U = R1 − 6.
        var counts = new int[13];
        for (var m = 0; m < 1 << 7; m++)
        {
            if (System.Numerics.BitOperations.PopCount((uint)m) != 3) continue;
            var r = 0;
            for (var i = 0; i < 7; i++) if (((m >> i) & 1) == 1) r += i + 1;
            counts[r - 6]++;
        }
        var x = new double[] { 1, 5, 6 };
        var y = new double[] { 2, 3, 4, 7 };
        var res = Stats.MannWhitneyU(x, y, alternative: Alternative.Greater, method: "exact");
        var u = (int)res.Statistic;
        var tail = counts.Skip(u).Sum() / 35.0;
        Near(tail, res.Pvalue, 1e-14, 0, "P(U >= u)");
    }

    [Fact]
    public void WilcoxonMatchesScipy()
    {
        foreach (var (name, alt) in Alternatives)
        {
            var r = Stats.Wilcoxon(R.W12, alternative: alt);
            Close($"wilcoxon_exact/{name}", Rt, 1e-14, r.Statistic, r.Pvalue);
            r = Stats.Wilcoxon(R.PA, R.PB, alternative: alt);
            Close($"wilcoxon_paired/{name}", Rt, 1e-14, r.Statistic, r.Pvalue);
            foreach (var zm in new[] { "wilcox", "pratt", "zsplit" })
            {
                r = Stats.Wilcoxon(R.WT, zeroMethod: zm, alternative: alt);
                Close($"wilcoxon_perm/{zm}/{name}", Rt, 1e-14, r.Statistic, r.Pvalue);
                foreach (var corr in new[] { false, true })
                {
                    var key = corr ? "True" : "False";
                    r = Stats.Wilcoxon(R.WBIG, zeroMethod: zm, correction: corr, alternative: alt);
                    Close($"wilcoxon_asym/{zm}/{key}/{name}", Rt, 1e-14, r.Statistic, r.Pvalue);
                    r = Stats.Wilcoxon(R.WT, zeroMethod: zm, correction: corr, alternative: alt, method: "asymptotic");
                    Close($"wilcoxon_asym_small/{zm}/{key}/{name}", Rt, 1e-14, r.Statistic, r.Pvalue);
                }
            }
            r = Stats.Wilcoxon(R.WT, alternative: alt, method: "exact");
            Close($"wilcoxon_exact_ties/{name}", Rt, 1e-14, r.Statistic, r.Pvalue);
        }
    }
}
